&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_vsdjv4j4qn3d&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Saadet Partisi Genel Başkanı Mahmut Arıkan&amp;rsquo;ın Grup Toplantısı Konuşması&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;D&amp;uuml;n maalesef millet&amp;ccedil;e i&amp;ccedil;imizi yakan elim bir kaza yaşadık. Azerbaycan&amp;#39;dan T&amp;uuml;rkiye&amp;#39;ye d&amp;ouml;nen asker&amp;icirc; kargo u&amp;ccedil;ağımız, ne yazık ki G&amp;uuml;rcistan sınırında kaza kırıma uğramış 20 askerimiz şehit olmuştur.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;T&amp;uuml;m şehitlerimize Allah&amp;#39;tan rahmet; ailelerine, yakınlarına, silah arkadaşlarına ve aziz milletimize sabır ve başsağlığı diliyorum. Bu elim kazanın kesin nedeni kamuoyunda hi&amp;ccedil;bir ş&amp;uuml;pheye yer bırakmayacak şekilde titizlikle incelenmeli ve milletimizle paylaşılmalıdır.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kazanın hemen ardından ortaya atılan birtakım vahim iddialar bir an &amp;ouml;nce aydınlatılmalıdır. Bunların başında u&amp;ccedil;ağın eski olması konusu var. U&amp;ccedil;ağın 1963 yılından itibaren kullanıldığı&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;ve Suudi Arabistan&amp;#39;dan ikinci el olarak alındığı iddiası doğru mudur?&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kahraman askerlerimizin, eski ve bakımsız olduğu s&amp;ouml;ylenen bir u&amp;ccedil;akla uluslararası yolculuk yapması izaha muhta&amp;ccedil;tır.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Enkaza el koyan, kaza kırım ekibinin yapacağı incelemeler sonucunda ortaya &amp;ccedil;ıkacak raporun kamuoyuna a&amp;ccedil;ıklanması bir zaruriyettir.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Son yıllarda yetersiz veya sağlam olmayan ekipmanlar sebebiyle şehit vermek, ne aziz milletimizin ne de T&amp;uuml;rkiye&amp;#39;nin hak ettiği bir durum değildir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu kazanın son olmasını temenni ediyor, aziz milletimize bir kez daha başsağlığı diliyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828275&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;12 KASIM: AFET HAZIRLIK G&amp;Uuml;N&amp;Uuml; VE DEPREM GER&amp;Ccedil;EĞİ&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bug&amp;uuml;n 12 Kasım &amp;Ccedil;arşamba. 12 Kasım aynı zamanda, &amp;ldquo;Afete Hazırlık G&amp;uuml;n&amp;uuml;&amp;rdquo;.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;1999 G&amp;ouml;lc&amp;uuml;k Depreminin acısıyla ilan edilen bu &amp;ouml;zel g&amp;uuml;n; Deprem &amp;ouml;ncesi, deprem anı ve sonrasında alınması gereken hayati &amp;ouml;nlemlerin hafızalarımıza kazınmasını hedefliyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Elbette bireysel g&amp;ouml;revlerimiz var. Ancak burada en b&amp;uuml;y&amp;uuml;k g&amp;ouml;rev; &amp;ccedil;ok uzun zamandır T&amp;uuml;rkiye&amp;rsquo;yi y&amp;ouml;neten, &amp;ldquo;iktidara&amp;rdquo; d&amp;uuml;ş&amp;uuml;yor. &amp;Ccedil;&amp;uuml;nk&amp;uuml; birey ne kadar dikkatli olursa olsun, eğer şehirlerimiz plansızsa, binalar denetlenmiyorsa, afet eğitimi yaygın değilse, sonu&amp;ccedil; -maalesef- değişmiyor&amp;hellip;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Tam da bug&amp;uuml;n sormak zorundayım: Hazır mıyız&amp;hellip;Hayır! -maalesef- Hen&amp;uuml;z hazır değiliz&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828276&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;DEPREM GER&amp;Ccedil;EĞİ&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Unutmamalıyız ki, T&amp;uuml;rkiye bir deprem &amp;uuml;lkesi. Bizler unutsak da&amp;nbsp;deprem kendini unutturmuyor.&amp;nbsp;Son haftalarda &amp;ouml;zellikle Sındırgı ve &amp;ccedil;evresinde meydana gelen sarsıntılar, her defasında hepimizin y&amp;uuml;reğini ağzına getiriyor.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;Sesimi duyan var mı?&amp;rdquo; sorusu bir kez daha y&amp;uuml;reklerimizi yakmadan, on binlerce insanımızı bir kez daha depreme kurban vermeden &amp;uuml;lkemizdeki yapı stoğunu bir an &amp;ouml;nce depreme hazırlıklı hale getirmeliyiz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;T&amp;uuml;rkiye tam anlamıyla depreme hazır hale gelmeden, bu &amp;uuml;lkenin birinci g&amp;uuml;ndemi her zaman&amp;nbsp;deprem&amp;nbsp;ve&amp;nbsp;depreme hazırlıkolmalıdır! Bunu yapacak olanda iktidardır!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828277&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;BİR &amp;Uuml;LKE NASIL Y&amp;Ouml;NETİLEMEZ: GEBZE, FATSA VE DİLOVASI&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İktidarın beceriksizlikleri canımızı acıtmaya devam ediyor.&amp;nbsp;Bir &amp;uuml;lke nasıl y&amp;ouml;netilemez?&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Buna dair d&amp;ouml;rt &amp;ouml;rnek vereceğim:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;1- Gebze&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;2- Fatsa&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;3- Dilovası&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;4- Diyarbakır&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Ouml;ncelikle yitirdiğimiz t&amp;uuml;m canlara Allah&amp;rsquo;tan rahmet, acılı ailelerine sabırlar diliyorum. 15 g&amp;uuml;n &amp;ouml;nce Gebze&amp;rsquo;de bir bina &amp;ccedil;&amp;ouml;kt&amp;uuml;, bir aile dağıldı&amp;hellip;T&amp;uuml;m T&amp;uuml;rkiye su&amp;ccedil;lu, bakanlık mı belediye mi tartışmalarını, CİMER şikayetlerini canlı yayında izledi&amp;hellip;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Altı g&amp;uuml;n &amp;ouml;nce; Fatsa&amp;rsquo;da bir taş ocağında g&amp;ouml;&amp;ccedil;&amp;uuml;k meydana geldi. Cansız bedenine ulaşılan iş makinesi operat&amp;ouml;r&amp;uuml; Burak Kilci, 25 yaşındaydı, 3 ay &amp;ouml;nce evlenmişti baba olmaya hazırlanıyordu.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Hen&amp;uuml;z kendisine ulaşılamayan kamyon şof&amp;ouml;r&amp;uuml; Ahmet Şahin; 75 yaşındaydı. Gebze&amp;rsquo;ye, Fatsa&amp;rsquo;ya &amp;uuml;z&amp;uuml;l&amp;uuml;rken; d&amp;ouml;rt g&amp;uuml;n &amp;ouml;nce Dilovası&amp;rsquo;nda bir kozmetik fabrikasında yangın &amp;ccedil;ıktı. Hepsi kadın, &amp;uuml;&amp;ccedil;&amp;uuml; &amp;ccedil;ocuk altı insanımız hayatını kaybetti.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Patlayan yer ile İŞKUR binası arasında sadece bir bina var. &amp;ldquo;K&amp;uuml;resel akt&amp;ouml;r&amp;rdquo; olduğunu iddia eden iktidar, kamu binalarının hemen yanındaki trajediden, s&amp;ouml;m&amp;uuml;r&amp;uuml;den habersiz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Duyarlı bir kardeşimiz diyor ki:&amp;nbsp;&amp;ldquo;burada insanlar sigortasız, &amp;ouml;nlemsiz &amp;ccedil;alışıyor ve &amp;ccedil;ocuk iş&amp;ccedil;iler var.&amp;rdquo;&amp;nbsp;Burada da,&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;bu dilek&amp;ccedil;eye CİMER tarafından verilen cevap var.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ne diyor vatandaşımıza;&amp;nbsp;&amp;ldquo;sigortasız &amp;ccedil;alıştırılan iş&amp;ccedil;ilerin isim, soy isim ve TC kimlik numaralarını bize atın, bizde işlem yapalım.&amp;rdquo;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu nasıl bir zihniyet Allah aşkına ya? Denetim mekanizmasını devletin kurumlarımı yapacak, vatandaş mı yapacak?&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu iş yerine yapılmayan denetimler y&amp;uuml;z&amp;uuml;nden; 15 yaşındaki Nisanur Taşdemir, yine 15 yaşındaki Cansu Esatoğlu, 17 yaşındaki Tuğba Taşdemir, 31 yaşındaki Esma Gikan ve 52 yaşındaki Hanım G&amp;uuml;lek vefat etti. Vefat eden kadınlardan &amp;uuml;&amp;ccedil;&amp;uuml; &amp;ccedil;ocuk!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Gebze&amp;rsquo;ye, Fatsa&amp;rsquo;ya, Dilovası&amp;rsquo;na &amp;uuml;z&amp;uuml;l&amp;uuml;rken d&amp;uuml;nde, Diyarbakır&amp;rsquo;da k&amp;ouml;pr&amp;uuml; inşaatında meydana gelen &amp;ccedil;&amp;ouml;kmede, 3 kardeşimiz daha hayatını kaybetti.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ne Gebze&amp;rsquo;de Ne Fatsa&amp;rsquo;da, Ne Dilovası&amp;rsquo;nda, Nede Diyarbakır&amp;rsquo;da yaşananlar&amp;nbsp;kaza değil cinayettir!&amp;nbsp;Sebebi insanı &amp;ouml;ncelemeyen, para odaklı vahşi sistemdir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu &amp;uuml;lkede, insanımızın hayatı bu kadar mı ucuz? İnsanımızın alın teri, emeği bu kadar mı ucuz? Sistematik hale gelmiş bu cinayetlerde kabahat; sadece alt kademelerde &amp;ccedil;alışan memurlarda mı? Bunca &amp;ouml;l&amp;uuml;m&amp;uuml;n ardından; Hangi en &amp;uuml;st makamda oturanlardan biri istifa etti? Mahkemeler, savcılar, h&amp;acirc;kimler, hangi en &amp;uuml;st makama ihmalden ve sorumluğundan &amp;ouml;t&amp;uuml;r&amp;uuml; ceza verebildi? Peş peşe yaşanılan bu facialar; kayırmacılığın, sistematik keyfiliğin ve zirve yapmış&amp;nbsp;liyakatsizliğin&amp;nbsp;neticesidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828278&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;T&amp;Uuml;RKİYE BİR HUKUK DEVLETİ Mİ?&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Şimdi herkesin aklındaki soru şu: Acaba Gebze i&amp;ccedil;in, Dilovası i&amp;ccedil;in adalet sağlanacak mı? Acaba hukuk ger&amp;ccedil;ekten işleyecek mi? iktidar cephesinden sık&amp;ccedil;a duyuyoruz: &amp;ldquo;T&amp;uuml;rkiye bir hukuk devletidir.&amp;rdquo;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;T&amp;uuml;rkiye&amp;rsquo;de hukuk mağdurları arttık&amp;ccedil;a, mağdurların feryadı arşa y&amp;uuml;kseldik&amp;ccedil;e, iktidar bu c&amp;uuml;mleyi daha da y&amp;uuml;ksek sesle daha da fazla tekrarlıyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Yerel mahkemelerin, Anayasa Mahkemesi kararını yok saydığı bir &amp;uuml;lkede, hukuk &amp;ldquo;s&amp;ouml;zle&amp;rdquo; değil, &amp;ldquo;icraatla&amp;rdquo; sağlanır!&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İktidar mensubu hi&amp;ccedil; kimseye dokunulamadığı bir &amp;uuml;lkede belki &amp;ldquo;yargı var&amp;rdquo; diyebilirsiniz!&amp;nbsp;Ama! Adalet var diyemezsiniz! Eğer bu &amp;uuml;lkede adalet olsaydı:&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;Burak Kilci, Ahmet Şahin, Nisanur Taşdemir, Cansu Esatoğlu, Tuğba Taşdemir hala yaşıyor olurdu. Bu kaza denilen cinayetler yaşanmamış olurdu!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828279&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İZNİK VE PAPA&amp;rsquo;NIN ZİYARETİ&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;D&amp;uuml;nya&amp;rsquo;nın g&amp;ouml;zleri bizim b&amp;ouml;lgemizin &amp;uuml;zerinde. Bir yanda İsrail&amp;rsquo;in b&amp;ouml;lgemize y&amp;ouml;nelik tehditleri, diğer yanda Amerika&amp;rsquo;nın yeni planları. Şimdi bir de b&amp;ouml;lgeye dahil olma niyetinde olan yeni akt&amp;ouml;rler sahnede.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu bağlamda; Papa 14. Leo&amp;rsquo;nun İznik Konsili&amp;rsquo;nin 1700&amp;rsquo;&amp;uuml;nc&amp;uuml; yılı m&amp;uuml;nasebetiyle yapacağı İznik ziyaretini ve kamuoyuna yansımalarını dikkatle takip ediyoruz. Ş&amp;uuml;phe ile takip ediyoruz:&amp;nbsp;İznik&amp;rsquo;te &amp;lsquo;Yeni Vatikan&amp;rsquo; mı Kuruluyor?&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İznik&amp;rsquo;te b&amp;uuml;y&amp;uuml;k bir hac organizasyonuna imk&amp;acirc;n verecek bir dini turizm yatırımı teklifinin g&amp;uuml;ndeme gelmesi, &amp;uuml;lkemizin tarih&amp;icirc; ve k&amp;uuml;lt&amp;uuml;rel mirası &amp;uuml;zerinde kimin s&amp;ouml;z sahibi olacağı meselesini yeniden tartışmaya a&amp;ccedil;maktadır. T&amp;uuml;rkiye, inan&amp;ccedil;ların ve medeniyetlerin kesişim yeridir; bu zenginlik elbette değerlidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ancak hi&amp;ccedil;bir dış akt&amp;ouml;r&amp;uuml;n, &amp;ouml;zellikle de devlet-dini otorite karışımının g&amp;uuml;&amp;ccedil;l&amp;uuml; olduğu bir yapının,&amp;nbsp;&amp;nbsp;bizim egemenlik alanımız i&amp;ccedil;inde ayrıcalıklı bir konum elde etmesine kayıtsız kalamayız. Bu mesele, sadece ekonomik getiri veya turizm potansiyeli &amp;uuml;zerinden tartışılamaz.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu ziyaretin kapsamı ve tesisin &amp;ouml;l&amp;ccedil;eği, yalnızca turistik bir yatırımın &amp;ouml;tesinde bir &amp;ldquo;&amp;ouml;zel stat&amp;uuml; alanı&amp;rdquo; oluşturma ihtimalini g&amp;uuml;ndeme getirmektedir.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Eğer planlanan b&amp;ouml;lge, uluslararası dini otoritenin &amp;ouml;zel hukuki stat&amp;uuml;ye sahip bir alanı gibi d&amp;uuml;ş&amp;uuml;n&amp;uuml;l&amp;uuml;yorsa, bu T&amp;uuml;rkiye&amp;rsquo;nin egemenlik alanına doğrudan temas eden kritik bir konudur. Bu nedenle konu a&amp;ccedil;ık, şeffaf ve kamuoyuna hesap verebilir bi&amp;ccedil;imde tartışılmalıdır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;ABD Başkan Yardımcısı&amp;nbsp;&amp;nbsp;Vance&amp;rsquo;in (Vens&amp;rsquo;in) katılımı, bu s&amp;uuml;recin sadece Vatikan&amp;rsquo;a ait bir girişim olmadığını, aynı zamanda k&amp;uuml;resel politik ve jeostratejik boyutlara sahip olabileceğini g&amp;ouml;stermektedir.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu ziyaretin s&amp;ouml;zde &amp;ldquo;dinler arası diyalog&amp;rdquo; gibi Siyonist bir projenin aşaması olarak takdim edildiğini g&amp;ouml;r&amp;uuml;yoruz. Burada mesele turizm değil, yumuşak g&amp;uuml;&amp;ccedil; alanlarının yeniden dizaynıdır. T&amp;uuml;rkiye, bu adımı kendi egemenlik perspektifinden değerlendirmelidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Buradan iktidara sesleniyorum; &amp;uuml;lkemizin yumuşak g&amp;uuml;c&amp;uuml;n&amp;uuml; doğru kullanın, ABD&amp;rsquo;nin, Vatikan&amp;rsquo;ın coğrafyamızı kuşatma hedeflerine karşı uyanık olun ve bu ziyaretin onlar i&amp;ccedil;in asla bir siyasi kazanım olmasına m&amp;uuml;saade etmeyin.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Biz; kendi inan&amp;ccedil;ları gereği, &amp;uuml;lkemizde bulunan ve kutsal kabul edilen mekanları ziyaret eden insanlara gereken nezaketi, ev sahipliğini yaparız! Ancak! kendi &amp;uuml;lkemizin, coğrafyamızın hukukunu da korumaktan zerre geri adım atmamalıyız!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828280&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;BM BİRLEŞMİŞ MİLLET 30. İKLİM KRİZİ&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Biz bu toplantıyı yaptığımız esnada Birleşmiş Milletlerin 30&amp;rsquo;uncu İklim Değişikliği Toplantısı ger&amp;ccedil;ekleştiriliyor. İkinci kez se&amp;ccedil;ildikten sonra Paris İklim Anlaşması&amp;rsquo;ndan tekrar &amp;ccedil;ekileceğini s&amp;ouml;yleyen Trump&amp;rsquo;ın toplantıya katılıp katılmayacağı hen&amp;uuml;z belli değil.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Katılır katılmaz bilemeyiz ama bizim i&amp;ccedil;in net olan bilgi şu: ABD ve İsrail&amp;rsquo;in &amp;ccedil;ıkarları s&amp;ouml;z konusu olduğunda Trump d&amp;uuml;nyanın geri kalanını ateşe vermekte zerre teredd&amp;uuml;t etmez.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İklim Zirvelerinde; verilen taahh&amp;uuml;tler, alınan kararlar, iklim değişikliğinin &amp;ouml;n&amp;uuml;ne ge&amp;ccedil;me &amp;ccedil;abaları olarak lanse ediliyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Oysa yapılanlar; Kapitalizmi yeşile boyamaktan başka bir şey değildir.&amp;nbsp;&amp;nbsp;Bunun adı da &amp;ldquo;greenwashing&amp;rdquo;tir.&amp;nbsp;Yani yeşil badanacılıktır, yeşil aklamadır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu toplantılarda olup biten k&amp;uuml;resel sermayenin kendi a&amp;ccedil;g&amp;ouml;zl&amp;uuml;l&amp;uuml;ğ&amp;uuml;n&amp;uuml;n bedelini, kontrol altında tuttukları h&amp;uuml;k&amp;uuml;metler vasıtasıyla savunmasız yoksul insanlara &amp;ouml;detme &amp;ccedil;abasıdır.&amp;nbsp;İklimi değiştirme politikalarının m&amp;uuml;sebbipleri iklim değişikliğinin &amp;ouml;n&amp;uuml;ne ge&amp;ccedil;emez.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/h1&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828281&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;SU KRİZİ&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Elbette T&amp;uuml;rkiye&amp;rsquo;de bundan payını alıyor. İktidarın &amp;ouml;zellikle son d&amp;ouml;nemde; iktidarda kalabilmek uğruna, en değerli madenlerini k&amp;uuml;resel emperyalist şirketlere, &amp;ccedil;ekmesinin bedelini &amp;ouml;d&amp;uuml;yor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu peşkeşlerin neticesinde; su kaynaklarımız kullanılamaz hale geliyor, ormanlarımız yok ediliyor, insanlarımız sağlığını yitiriyor. Bu sorunun ortaya &amp;ccedil;ıkmasında değişen iklim şartları kadar, yanlış su politikası da etkili oluyor. Burada hem vatandaşlarımıza hem de devlete &amp;ouml;devler ve g&amp;ouml;revler d&amp;uuml;ş&amp;uuml;yor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bizler&amp;nbsp;&amp;ldquo;akarsu kenarında bile olsanız suyu israf etmeyiniz.&amp;rdquo;&amp;nbsp;diyen bir medeniyetin evlatlarız. Her anlamda suyu israf etmemek, bireylerin &amp;uuml;zerine d&amp;uuml;şmektedir. Ancak esas g&amp;ouml;rev, doğru ve yeterli politikalar &amp;uuml;retmek &amp;uuml;zere devlete d&amp;uuml;şmektedir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Fakat &amp;uuml;lkemize ş&amp;ouml;yle bir bakıyoruz: su sorunu yaşayan şehirlerde ya su firmaları suyun nerdeyse tamamına el koymuş ya hi&amp;ccedil; planlama yapılmamış, ya da maden arama şirketleri, şehrin kullandığından daha fazla su kullanmış.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Evet yer altı varlıklarımız elbette en b&amp;uuml;y&amp;uuml;k zenginliğimiz. Fakat hi&amp;ccedil;bir maden -altını &amp;ccedil;iziyorum- su kadar &amp;ouml;nemli olamaz. &amp;Uuml;lkemiz zannedildiği gibi &amp;ldquo;su zengini&amp;rdquo; bir &amp;uuml;lke değil. Bug&amp;uuml;n su krizini bir &amp;ccedil;evre meselesi olarak g&amp;ouml;rmeliyiz, ama aynı zamanda bir&amp;nbsp;g&amp;uuml;venlik ve adalet meselesi&amp;nbsp;olarak da g&amp;ouml;rmek zorundayız.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc211939902&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc213828282&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;BİZ NE YAPACAĞIZ&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bizim su politikamız; t&amp;uuml;ketimi değil, korumayı ve yeniden kullanımı esas almalıdır. Peki bu &amp;ccedil;er&amp;ccedil;evede biz ne yapacağız?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ulusal Su Y&amp;ouml;netimi Yasası &amp;ccedil;ıkararak her il i&amp;ccedil;in &amp;ldquo;su b&amp;uuml;t&amp;ccedil;esi&amp;rdquo; hazırlayacağız. Su havzalarını madencilik ve enerji faaliyetlerine karşı koruma altına alacağız. Sanayi ve madenlerde su kullanım kotaları belirleyip ihlallerine ağır yaptırımlar uygulayacağız. Sens&amp;ouml;r ve veri temelli &amp;ldquo;akıllı sulama teknolojilerini&amp;rdquo; yaygınlaştıracağız. Yağmur suyu hasadını şehir planlamasının zorunlu unsuru haline getireceğiz. Su fiyatlandırmasını gelir d&amp;uuml;zeyine ve kullanım amacına g&amp;ouml;re adil bi&amp;ccedil;imde d&amp;uuml;zenleyeceğiz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Su gibi aziz olmanın yolu aziz milletimizin suyunu korumaktan, maden şirketlerine, b&amp;ouml;lgesel akt&amp;ouml;rlere peşkeş &amp;ccedil;ekmemekten ge&amp;ccedil;er!&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İnşallah biz, bunun gayreti i&amp;ccedil;erisinde olacağız.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828283&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;BAHİS&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bir de bahis meselesi var&amp;hellip; &amp;Uuml;lkemizde &amp;ccedil;&amp;uuml;r&amp;uuml;me hat safhaya ulaştı, bataklık bile artık alarm veriyor! Maalesef &amp;uuml;lkede şaibesiz bir kurum, lekesiz bir sekt&amp;ouml;r neredeyse kalmadı.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Biz yıllardır s&amp;ouml;yl&amp;uuml;yoruz: adalet mekanizması işlemezse, denetim mekanizmaları ciddiyetini kaybederse, kurumlar şeffaf olmazsa, &amp;ccedil;&amp;uuml;r&amp;uuml;me &amp;ouml;nce dipten başlar, sonra herkesi sarar.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bug&amp;uuml;n soruyoruz: bu kadar hakem, bu kadar futbolcu, bu kadar menajer bahis &amp;ccedil;arkının i&amp;ccedil;inde d&amp;ouml;nerken devlet neredeydi?&amp;nbsp;İstihbarat bu &amp;uuml;lkede ne iş yapıyor? Neden m&amp;uuml;dahaleler, irin cerahat patladıktan sonra yapılıyor? Eğer ahlaki bir duruş inşa edilmezse, sadece su&amp;ccedil;luları yakalamak ancak g&amp;uuml;n&amp;uuml; kurtarır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Futbol, bu milletin ortak sevinciyken g&amp;uuml;venin kaybolduğu bir alana d&amp;ouml;n&amp;uuml;şt&amp;uuml;. Biz olaya sadece ma&amp;ccedil; sonu&amp;ccedil;ları a&amp;ccedil;ısından değil, devletin yeniden itibar kazanması, adaletin yeniden tesis edilmesi, kurumların bağımsızlığının ve temizliğinin sağlanması a&amp;ccedil;ısından bakıyoruz.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Temiz siyaset, temiz toplum olmadan bu yaralar kapanmaz, temiz bir spor olmaz arkadaşlar.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828284&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İKTİDARIN EKONOMİ TAHMİNLERİ Nİ&amp;Ccedil;İN TUTMUYOR?&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Uuml;lkemizde hepimizin malumu sadece bahis krizi yok! Hi&amp;ccedil; bitmeyen, her ge&amp;ccedil;en g&amp;uuml;n daha kesif hale gelen bir ekonomik kriz ile karşı karşıyayız.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Hatırlayacaksınız, iktidar; 2024&amp;rsquo;te; 2025 yılı enflasyon beklentisini %25 olarak belirlemişti, asgari &amp;uuml;cretli, memur, emekli başta olmak &amp;uuml;zere milyonlarca vatandaşımızın maaşına bu tahmin &amp;uuml;zerinden zam yapmıştı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ama Merkez Bankası ge&amp;ccedil;tiğimiz hafta bu beklentiyi %25&amp;#39;ten %33&amp;#39;e &amp;ccedil;ekti! Şimdi; milyonlarca vatandaşımız adına sormak istiyorum; %25 &amp;uuml;zerinden haklarını gasp ettiğiniz asgar&amp;icirc; &amp;uuml;cretlinin enflasyon farkını yıl bitmeden iade edecek misiniz? Gelecek yılın zam oranlarını a&amp;ccedil;ıklarken, %33 &amp;uuml;zerinden mi zam vereceksiniz yoksa 2026 tahmini olan ve asla tutturamayacağınız %13 &amp;uuml;zerinden mi vereceksiniz? Yoksa &amp;ldquo;Biz tahmin ederiz, siz yine bedel &amp;ouml;dersiniz&amp;rdquo; mi diyeceksiniz?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Beyler! Sizin tutturamadığınız tahminlerinizin, ger&amp;ccedil;ekleştiremediğiniz hedeflerinizin, plansız-programsız icraatlarınızın bedelini bu &amp;uuml;lkede insanlar pazarda, faturada, kirada &amp;ouml;demekten bıktı usandı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu y&amp;uuml;zden; sizler, biz &amp;ldquo;olursa olur, olmazsa ne yapalım&amp;rdquo; diyecek makamlarda değilsiniz.&amp;nbsp;&amp;nbsp;Eğer bu makamların sorumluluğunu alamayacaksınız, &amp;ccedil;ekilin kenara bu işi biz halledelim!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bizler buradan uyarıyoruz; sizin enflasyon beklentinize g&amp;ouml;re zam yapma planınız &amp;ccedil;&amp;ouml;km&amp;uuml;şt&amp;uuml;r. Sakın ha! Aklınızdan gelecek yılın zammını -yine- &amp;ldquo;beklenti&amp;rdquo; rakamlarına g&amp;ouml;re yapmak ge&amp;ccedil;mesin. Emeklinin, Asgari &amp;uuml;cretlinin, iş&amp;ccedil;inin, emek&amp;ccedil;inin hakkı; en d&amp;uuml;ş&amp;uuml;k yoksulluk sınırı olmalıdır!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;h1 style=&quot;margin-left:5px; text-align:justify&quot;&gt;&amp;nbsp;&lt;/h1&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828285&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;SİZE ALDIĞINIZ VERGİ AZ GELİYOR!&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Millet y&amp;uuml;ksek enflasyon, d&amp;uuml;ş&amp;uuml;k &amp;uuml;cret zulm&amp;uuml;n&amp;uuml;n altında ezilirken, Sayın Şimşek&amp;rsquo;in Plan ve B&amp;uuml;t&amp;ccedil;e komisyonundaki &amp;ldquo;topladığımız vergi az&amp;rdquo; a&amp;ccedil;ıklaması akıllara durgunluk verecek cinsten bir a&amp;ccedil;ıklama!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828286&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;RİZELİ KARDEŞİME KULAK VERİN!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Hafta sonu, Karadeniz&amp;rsquo;imizde yeşilin kalesi Rize&amp;rsquo;deydim. Orada Rizeli hemşerilerimizle buluştuk, esnafımızla, gen&amp;ccedil;lerimizle &amp;ccedil;ay i&amp;ccedil;ip dertleştik. &amp;Uuml;lkemizin her yerinde olduğu gibi Rize&amp;rsquo;de de İnsanımızın hali perişan. Orada bir esnaf kardeşimin feryadı var. Onu aynen size aktarmak istiyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;margin-left:57px; margin-right:38px; text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;Ben Mehmet Şimşek&amp;rsquo;i artık dinlemiyorum. Ben araştırdım d&amp;uuml;nyanın hi&amp;ccedil;bir yerinde b&amp;ouml;yle bir şey bulamadım. &amp;Uuml;r&amp;uuml;nler %1 ile bize geliyor %10 ile &amp;ccedil;ıkıyor. Yani cironun y&amp;uuml;zde 9&amp;rsquo;unu otomatik devlet alıyor bizden. Verelim, ama hepimiz verelim. Ama adil olsun. Ben 3 tane masa ile birlikte her ay 60 bin lira vergi veriyorum. Vergiyi yetiştirebilmek i&amp;ccedil;in hi&amp;ccedil;bir g&amp;uuml;n izin yapmıyorum. Hasta olma şansım yok!&amp;rdquo;&lt;/span&gt;&lt;/em&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Evet Sayın Şimşek! T&amp;uuml;rkiye&amp;rsquo;nin ger&amp;ccedil;eğini, milyonlarca esnaf adına bu kardeşimiz haykırıyor!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;2026&amp;rsquo;da toplayacağınız&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;15,6 trilyon vergi var, sizde bizde biliyoruz 15,6 trilyon size yine yetmeyecek.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828287&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;EMEKLİ KARDEŞİME KULAK VERİN&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ge&amp;ccedil;tiğimiz g&amp;uuml;n, emeklilikte Yaşa Takılanlar ve Emekliler Federasyonu ile beraberdik. Sayın Başkan ve Y&amp;ouml;netim Kuruluna &amp;ccedil;ok teşekk&amp;uuml;r ediyorum. Bug&amp;uuml;n iki b&amp;uuml;y&amp;uuml;k sorunumuz var:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Birincisi; yoksulluk, a&amp;ccedil;lık ve en son yokluk sınırına dayanan emekli maaşları.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İkinci; EYT meselesi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Rizeli kardeşim gibi, Emeklilerimizin s&amp;ouml;ylediklerini aynen aktaracağım: Diyorlar ki:&amp;nbsp;&amp;ldquo;Başkanım, eskiden emekli maaşımızla kiramızı &amp;ouml;d&amp;uuml;yor ge&amp;ccedil;inebiliyorduk. Bug&amp;uuml;n kirayı bile &amp;ouml;deyemiyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Başka bir b&amp;uuml;y&amp;uuml;ğ&amp;uuml;m&amp;uuml;z:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;Mutfak alışverişi yapmak i&amp;ccedil;in eşim &amp;ccedil;alışıyor, ancak hasta. Ağırlaştığında yiyecek bir şey alamıyoruz.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bir başkası:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;Başkanım bayram olunca perdeleri &amp;ccedil;ekiyoruz, kapıdaki ayakkabıları alıyoruz, evde sessizce oturuyoruz.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bir başkası:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;Bayram evde durmuyorum. Her g&amp;uuml;n bir &amp;ccedil;ocuğuma gidiyoruz.&amp;rdquo;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;diyor&amp;hellip;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İktidar yetkilileri, 16 milyon emeklimizin ahını alıyorsunuz. Şunu unutmayın mazlumun ahı, indirir şahı&amp;hellip;Bir &amp;uuml;lkenin b&amp;uuml;y&amp;uuml;kl&amp;uuml;ğ&amp;uuml;; emeklisine, iş&amp;ccedil;isine, memuruna verdiği değerden anlaşılır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bug&amp;uuml;n emeklimizin sesi duyulmuyorsa, o &amp;uuml;lkede adalet de kalkınma da eksiktir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828288&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;EYT MESELESİ K&amp;Ouml;KTEN &amp;Ccedil;&amp;Ouml;Z&amp;Uuml;LMEDİ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Mağduriyet sadece emekli aylığı değil, EYT meselesi var. Ve EYT Meselesi hala k&amp;ouml;kten &amp;ccedil;&amp;ouml;z&amp;uuml;lmedi. 8 Eyl&amp;uuml;l 1999 yılında sigortası başlayan ve prim g&amp;uuml;n sayısını dolduran bir vatandaş emekli olurken; sadece bir g&amp;uuml;n sonra yani 9 Eyl&amp;uuml;l 1999 yılında işe başlayıp prim g&amp;uuml;n sayısını dolduran bir vatandaşımız emeklilik i&amp;ccedil;in 60 yaşını beklemek zorunda.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu; trajikomik bir tablodur. Bir hak gaspıdır, adaletsiz bir uygulamadır. Se&amp;ccedil;im yatırımı olarak EYT d&amp;uuml;zenlemesi &amp;ccedil;ıkaran iktidar, geride kalan milyonlarca vatandaşımızın da mağduriyetini &amp;ccedil;&amp;ouml;zmekle m&amp;uuml;kelleftir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828289&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Ccedil;&amp;Ouml;Z&amp;Uuml;M TEKLİFİMİZ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Biz diyoruz ki; prim g&amp;uuml;n sayısını erken d&amp;ouml;nemde tamamlayan yurttaşımıza daha erken emeklilik hakkı tanıyalım. Bu yalnızca adil değil, aynı zamanda ekonomiktir. &amp;Ccedil;&amp;uuml;nk&amp;uuml; primler devlete erken d&amp;ouml;nemde, uzun vadeli ve sıfır faizli bir kaynak sağlar. Devlet bu kaynakla bor&amp;ccedil;lanma ihtiyacını azaltır, faiz giderinden kurtulur. Vatandaş da emeğinin karşılığını daha erken ve daha y&amp;uuml;ksek maaşla alır.&amp;nbsp;Yani hem devlet kazanır, hem vatandaş kazanır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Mevcut sistemde 20 yaşında işe başlamış, 20 yıl boyunca &amp;ccedil;alışıp primini dolduran yani devlete sıfır faizli bor&amp;ccedil; veren bir vatandaş, tam 20 yıl bekletiliyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Oysa bu s&amp;uuml;re kısaltılsa; kayıt dışı istihdam azalır, gen&amp;ccedil;lerin işe katılımı artar, vasıflı işg&amp;uuml;c&amp;uuml; y&amp;uuml;kselir, asgari &amp;uuml;cret, toplumun genel &amp;uuml;creti olmaktan &amp;ccedil;ıkar. En &amp;ouml;nemlisi, emeklilik bir &amp;ldquo;hak&amp;rdquo; olarak yeniden anlam kazanacaktır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828290&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;VATANDAŞIN KA&amp;Ccedil; EKMEĞİ VAR?&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Esnaf, emekli veya asgari &amp;uuml;cretli vatandaş &amp;ldquo;hakkına&amp;rdquo; yeniden kavuşmalı.&amp;nbsp;Bakınız arkadaşlar;&amp;nbsp;&amp;nbsp;Ortada vatandaşa&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;verilmesi gereken on ekmek var. T&amp;Uuml;İK&amp;rsquo;in a&amp;ccedil;ıkladığı rakamlar y&amp;uuml;z&amp;uuml;nden vatandaşın on ekmeği beşe d&amp;uuml;ş&amp;uuml;yor. Sayın Şimşek&amp;rsquo;in getirdiği vergilerle vatandaşın beş ekmeği ikiye d&amp;uuml;ş&amp;uuml;yor. Ama yetmemiş olacak ki Sayın Şimşek aldığımız iki ekmeğede yeni vergiler ve cezalarla g&amp;ouml;z dikiyor.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Biz de soruyoruz Sayın Şimşek: Daha neyini alacaksınız vatandaşın? Vatandaşın elinde ekmek mi bıraktınız? D&amp;uuml;n vermediğiniz ekmeğin hesabını verdiniz mi ki; Bug&amp;uuml;n verginin azlığından şikayet ediyorsunuz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828291&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;BURJUVACI DEĞİL AMA HALK&amp;Ccedil;I DA DEĞİL!&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Dahası Sn. Şimşek: &amp;ldquo;Benden burjuva sermayeci &amp;ccedil;ıkartamazsınız.&amp;rdquo; diyor. Sayın Şimşek&amp;rsquo;ten burjuva sermayeci &amp;ccedil;ıkar &amp;ccedil;ıkmaz o ayrı bir tartışma konusu, ancak Sayın Şimşek&amp;rsquo;ten&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;halkı d&amp;uuml;ş&amp;uuml;nen bir ekonomi bakanı&amp;rdquo; &amp;ccedil;ıkmayacağını gayet iyi biliyoruz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc213828292&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;23 YIL FİYASKOSU&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Malum Kasım ayındayız! 3 Kasım 2002, T&amp;uuml;rkiye siyasetinde bir miladın tarihiymiş. Bakalım &amp;ouml;yle mi?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bizzat Cumhurbaşkanı Recep Tayyip Erdoğan&amp;rsquo;ın ağzından d&amp;ouml;k&amp;uuml;len s&amp;ouml;zlerle son 23 yılın &amp;ouml;zetini, kendisinden dinleyelim:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;ul&gt;
	&lt;li style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;Ne istediler de vermedik?&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;Rabbim ve milletim bizi affetsin.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;K&amp;uuml;lt&amp;uuml;rel iktidarı tam olarak kuramadık.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;Ailede &amp;ccedil;&amp;ouml;z&amp;uuml;lme var.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;Gen&amp;ccedil;lerimiz ekranların esiri oldu.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;İyi niyetimiz suistimal edildi.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
