&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;İyi niyetimiz suistimal edildi.&amp;rdquo; &amp;rarr; Suistimal eden kim?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;AB bizi aldattı.&amp;rdquo; &amp;rarr; Peki biz ne &amp;ouml;ğrendik?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;K&amp;uuml;lt&amp;uuml;rel iktidarı kuramadık.&amp;rdquo; &amp;rarr; Peki neden?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

